import os
import json
from typing import Any, Dict, List, Optional

import requests


class OCRLayoutExtractor:
    """
    Extracts text blocks, lines, tables, and other layout elements from documents
    using the Google Cloud Document AI hosted API.
    """

    def __init__(
        self,
        project_id: Optional[str] = None,
        location: Optional[str] = None,
        processor_id: Optional[str] = None,
        api_key: Optional[str] = None,
    ) -> None:
        self.project_id = project_id or os.getenv("GOOGLE_CLOUD_PROJECT")
        self.location = location or os.getenv("GOOGLE_CLOUD_LOCATION", "us")
        self.processor_id = processor_id or os.getenv("DOCUMENT_AI_PROCESSOR_ID")
        self.api_key = api_key or os.getenv("GOOGLE_API_KEY")

        if not self.project_id:
            raise ValueError("Missing project_id or GOOGLE_CLOUD_PROJECT")
        if not self.processor_id:
            raise ValueError("Missing processor_id or DOCUMENT_AI_PROCESSOR_ID")
        if not self.api_key:
            raise ValueError("Missing api_key or GOOGLE_API_KEY")

        self.endpoint = (
            f"https://documentai.googleapis.com/v1/projects/{self.project_id}"
            f"/locations/{self.location}/processors/{self.processor_id}:process"
        )

    def extract_from_bytes(
        self,
        document_bytes: bytes,
        mime_type: str = "application/pdf",
    ) -> Dict[str, Any]:
        payload = {
            "rawDocument": {
                "content": document_bytes.decode("latin1"),
                "mimeType": mime_type,
            }
        }

        # Document AI expects base64-encoded content when using the REST API.
        # We keep the request payload correct by encoding properly.
        import base64

        payload["rawDocument"]["content"] = base64.b64encode(document_bytes).decode("utf-8")

        params = {"key": self.api_key}
        headers = {"Content-Type": "application/json"}

        response = requests.post(
            self.endpoint,
            params=params,
            headers=headers,
            data=json.dumps(payload),
            timeout=120,
        )
        response.raise_for_status()
        return self._normalize_response(response.json())

    def extract_from_file(
        self,
        file_path: str,
        mime_type: str = "application/pdf",
    ) -> Dict[str, Any]:
        with open(file_path, "rb") as f:
            return self.extract_from_bytes(f.read(), mime_type=mime_type)

    def _normalize_response(self, data: Dict[str, Any]) -> Dict[str, Any]:
        document = data.get("document", {})
        pages = document.get("pages", [])

        blocks: List[Dict[str, Any]] = []
        lines: List[Dict[str, Any]] = []
        tables: List[Dict[str, Any]] = []
        paragraphs: List[Dict[str, Any]] = []

        for page_index, page in enumerate(pages):
            for block in page.get("blocks", []):
                blocks.append(
                    {
                        "page": page_index + 1,
                        "layout": self._layout_to_dict(block.get("layout", {})),
                    }
                )

            for line in page.get("lines", []):
                lines.append(
                    {
                        "page": page_index + 1,
                        "layout": self._layout_to_dict(line.get("layout", {})),
                    }
                )

            for paragraph in page.get("paragraphs", []):
                paragraphs.append(
                    {
                        "page": page_index + 1,
                        "layout": self._layout_to_dict(paragraph.get("layout", {})),
                    }
                )

            for table in page.get("tables", []):
                tables.append(
                    {
                        "page": page_index + 1,
                        "layout": self._layout_to_dict(table.get("layout", {})),
                        "header_rows": self._extract_table_rows(table.get("headerRows", [])),
                        "body_rows": self._extract_table_rows(table.get("bodyRows", [])),
                    }
                )

        return {
            "text": document.get("text", ""),
            "blocks": blocks,
            "lines": lines,
            "paragraphs": paragraphs,
            "tables": tables,
            "full_document": document,
        }

    def _layout_to_dict(self, layout: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "text_anchor": layout.get("textAnchor", {}),
            "confidence": layout.get("confidence"),
            "bounding_poly": layout.get("boundingPoly", {}),
            "detected_languages": layout.get("detectedLanguages", []),
        }

    def _extract_table_rows(self, rows: List[Dict[str, Any]]) -> List[List[Dict[str, Any]]]:
        normalized_rows: List[List[Dict[str, Any]]] = []
        for row in rows:
            cells = []
            for cell in row.get("cells", []):
                cells.append(
                    {
                        "layout": self._layout_to_dict(cell.get("layout", {})),
                        "row_span": cell.get("rowSpan", 1),
                        "col_span": cell.get("colSpan", 1),
                    }
                )
            normalized_rows.append(cells)
        return normalized_rows


def extract_layout(
    file_path: str,
    project_id: Optional[str] = None,
    location: Optional[str] = None,
    processor_id: Optional[str] = None,
    api_key: Optional[str] = None,
    mime_type: str = "application/pdf",
) -> Dict[str, Any]:
    extractor = OCRLayoutExtractor(
        project_id=project_id,
        location=location,
        processor_id=processor_id,
        api_key=api_key,
    )
    return extractor.extract_from_file(file_path, mime_type=mime_type)
